// CloudtainerML rev0030 — Copy-head phase transition probe.
// Analytical/tiny simulator inspired by Bayesian copy-head phase-transition work.
// Not a trained-transformer reproduction. It asks which attention family gives lower
// loss + monitoring risk under tiny copy-task sample scales.
#include <bits/stdc++.h>
using namespace std;
static string q(const string&s){string o="\""; for(char c:s){if(c=='\"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'\"';}
static double sig(double x){if(x>35)return 1; if(x<-35)return 0; return 1.0/(1.0+exp(-x));}
struct Row{string regime,method; int L,V,samples; double pool_order,copy_order,loss,precursor,abruptness,compute_frac,monitor_risk,score;};
struct Regime{string name; double noise, copy_gain, prior_strength, monitor_weight; int L,V;};
static Row eval(const Regime&r,string m,int n){double L=r.L,V=r.V; double base=log(V)+0.18*r.noise; double n1=0.72*V*sqrt(log(L+2.0))*(1+r.prior_strength); double n2=2.20*V*log(L+2.0)*(1+0.45*r.prior_strength); double ns=1.15*V*log(V+2.0)*sqrt(L/16.0)*(1+0.25*r.prior_strength); double pool=0,copy=0,prec=0,abr=0,cost=1;
 if(m=="softmax_head"){double width=max(1.0,0.025*ns); copy=sig((n-ns)/width); pool=0.05*(1-copy); prec=0.05; abr=copy*(1-copy)*ns/width; cost=1.0;}
 else if(m=="linear_attention"){pool=sqrt(max(0.0,(n-n1)/max(1.0,n1))); pool=min(1.0,pool); copy=pool*sig((n-n2)/(0.32*n2+1)); prec=min(1.0,0.20+0.80*pool); abr=0.22*pool*(1-copy); cost=0.48;}
 else if(m=="annealed_softmax"){double warm=sig((n-0.55*ns)/(0.18*ns+1)); copy=sig((n-1.05*ns)/(0.075*ns+1)); pool=0.28*warm*(1-copy); prec=0.22+0.35*warm; abr=0.55*copy*(1-copy); cost=0.82;}
 else if(m=="linear_then_softmax_switch"){double linpool=sqrt(max(0.0,(n-n1)/max(1.0,n1))); linpool=min(1.0,linpool); double sw=sig((linpool-0.58)/0.08); double soft=sig((n-1.05*ns)/(0.08*ns+1)); double lcopy=linpool*sig((n-n2)/(0.32*n2+1)); copy=(1-sw)*lcopy+sw*soft; pool=(1-sw)*linpool+sw*0.05; prec=0.35+0.55*linpool; abr=0.32*sw*soft*(1-soft); cost=0.65+0.15*sw;}
 else { // sparsemax-ish / entmax-ish smoother normalization
   pool=sqrt(max(0.0,(n-0.9*n1)/max(1.0,n1))); pool=min(1.0,pool); copy=pool*sig((n-0.75*n2)/(0.42*n2+1)); prec=0.28+0.65*pool; abr=0.16*pool; cost=0.70;}
 double loss=base - r.copy_gain*(0.85*copy+0.25*pool) + 0.10*r.noise*(1-copy); double monitor=max(0.0,abr-prec)*r.monitor_weight + 0.04*(1-prec); double score=loss + monitor + 0.08*cost; return {r.name,m,r.L,r.V,n,pool,copy,loss,prec,abr,cost,monitor,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0030_COPY_HEAD_PHASE_SMOKE.json"; vector<Regime> regs={{"tiny_vocab_short_context",0.10,1.0,0.15,0.35,16,32},{"longer_context_copy",0.12,1.05,0.25,0.45,64,64},{"high_vocab_sparse_copy",0.16,1.15,0.35,0.50,32,256},{"noisy_copy_data",0.55,0.85,0.35,0.65,48,128},{"monitorability_weighted",0.18,1.0,0.20,1.05,64,128}}; vector<string> methods={"softmax_head","linear_attention","annealed_softmax","linear_then_softmax_switch","entmax_smoother"}; vector<Row> rows; map<string,int> wins, nonoracle; for(auto&r:regs){ vector<int> samples; int maxN=(int)(4.5*r.V*log(r.V+2.0)*sqrt(r.L/16.0)+100); for(double frac: {0.05,0.10,0.18,0.28,0.42,0.60,0.85,1.15,1.60,2.20,3.00}) samples.push_back(max(2,(int)round(maxN*frac))); for(int n:samples){vector<Row> cand; for(auto&m:methods)cand.push_back(eval(r,m,n)); auto best=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); wins[best->method]++; for(auto &x:cand) rows.push_back(x); }}
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0030\",\n  \"probe\": \"copy_head_phase_transition\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Softmax-like copying can score well after its boundary, but linear/annealed/hybrid variants expose monitorability and precursor tradeoffs; this is a tiny mechanistic phase screen, not a training proof.\",\n    \"screen_regret_fields\": [\"loss\",\"precursor\",\"abruptness\",\"monitor_risk\",\"compute_frac\",\"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"sequence_length\": "<<r.L<<", \"vocab_size\": "<<r.V<<", \"samples\": "<<r.samples<<", \"pool_order\": "<<r.pool_order<<", \"copy_order\": "<<r.copy_order<<", \"loss\": "<<r.loss<<", \"precursor\": "<<r.precursor<<", \"abruptness\": "<<r.abruptness<<", \"compute_frac\": "<<r.compute_frac<<", \"monitor_risk\": "<<r.monitor_risk<<", \"score\": "<<r.score<<"}"<<(i+1<rows.size()?",":"")<<"\n";} f<<"  ]\n}\n";}
